the-number-of-passengers-in-each-bus-ii:
WITH arrival_time_cte AS
(
    SELECT bus_id, b.arrival_time, capacity, count(passenger_id) AS prefix_sum
    FROM Buses b
    LEFT JOIN Passengers p
    ON p.arrival_time <= b.arrival_time
    GROUP BY bus_id
    ORDER BY arrival_time
)
SELECT bus_id, passengers_cnt
FROM
(
    SELECT bus_id, capacity, prefix_sum,
           @passengers_cnt := LEAST(capacity, prefix_sum-@accum) as passengers_cnt, 
           @accum := @accum + @passengers_cnt
    FROM arrival_time_cte,
         (SELECT @accum := 0,
                 @passengers_cnt := 0) init
) t
ORDER BY bus_id;

order-two-columns-independently:
SELECT first_col, second_col
FROM (
    SELECT first_col, ROW_NUMBER() OVER(ORDER BY first_col ASC) AS rnk
    FROM Data
) a
INNER JOIN (
    SELECT second_col, ROW_NUMBER() OVER(ORDER BY second_col DESC) AS rnk
    FROM Data
) b
ON a.rnk = b.rnk;

dynamic-pivoting-of-a-table:
CREATE PROCEDURE PivotProducts()
BEGIN
    SET SESSION group_concat_max_len = 1000000;
    SET @case_stmt = NULL;
    SELECT GROUP_CONCAT(
        DISTINCT CONCAT(
            'MIN(CASE WHEN store = "', store, '" THEN price END) AS ', store
        ) SEPARATOR ','
    )
    INTO @case_stmt
    FROM products;
    SET @sql_query = CONCAT('SELECT product_id, ', @case_stmt, ' FROM products GROUP BY product_id ORDER BY NULL');
    PREPARE sql_query FROM @sql_query;
    EXECUTE sql_query;
    DEALLOCATE PREPARE sql_query;
END;

dynamic-unpivoting-of-a-table:
CREATE PROCEDURE UnpivotProducts()
BEGIN
    SET SESSION group_concat_max_len = 1000000;
    SET @sql_query = NULL;
	  SELECT GROUP_CONCAT(
        CONCAT(
            'SELECT product_id, "', column_name, '" AS store, ', column_name, ' AS price FROM products WHERE ', column_name, ' IS NOT NULL'
        ) SEPARATOR ' UNION ALL '
    )
    INTO @sql_query
    FROM information_schema.columns
    WHERE table_name = 'products' AND column_name != 'product_id';
    PREPARE sql_query FROM @sql_query;
    EXECUTE sql_query;
    DEALLOCATE PREPARE sql_query;
END;

